solution.solution.cpp:
#include <cstdint>

struct HrParts { bool failed; std::uint32_t facility; std::uint32_t code; };

HrParts decode(std::uint32_t hr)
{
    return HrParts{
        (hr >> 31) != 0,
        (hr >> 16) & 0x7FFu,     // 11 bits
        hr & 0xFFFFu,            // 16 bits
    };
}

std::uint32_t fromWin32(std::uint32_t error)
{
    if (error == 0) return 0;
    return 0x80000000u | (7u << 16) | (error & 0xFFFFu);
}

unitTests:
TEST("access denied") { const HrParts p{ decode(0x80070005u) }; CHECK(p.failed); CHECK_EQ(p.facility, 7u); CHECK_EQ(p.code, 5u); }
TEST("a success code") { const HrParts p{ decode(0x00000001u) }; CHECK(!p.failed); CHECK_EQ(p.facility, 0u); CHECK_EQ(p.code, 1u); }
TEST("E_INVALIDARG") { const HrParts p{ decode(0x80070057u) }; CHECK(p.failed); CHECK_EQ(p.code, 0x57u); }
TEST("a COM error: facility 4") { const HrParts p{ decode(0x80040154u) }; CHECK(p.failed); CHECK_EQ(p.facility, 4u); CHECK_EQ(p.code, 0x154u); }
TEST("facility ignores the flag bits") { CHECK_EQ(decode(0xFFFFFFFFu).facility, 0x7FFu); CHECK_EQ(decode(0xFFFFFFFFu).code, 0xFFFFu); }
TEST("wrapping Win32 errors") { CHECK_EQ(fromWin32(2), 0x80070002u); CHECK_EQ(fromWin32(5), 0x80070005u); CHECK_EQ(fromWin32(1223), 0x800704C7u); }
TEST("zero stays success") { CHECK_EQ(fromWin32(0), 0u); }

